-- 034: Vorlagen LKav-Push W260 (Weg von KRORETTEF 100, de260) und LKav-Ausbau W260 (Fortsetzung).
update public.bau_vorlagen set name='LKav-Push W260', queue=$q$main:1;farm:1;storage:1;iron:4;wood:1;stone:1;wood:1;stone:1;wood:1;stone:1;main:2;barracks:2;iron:5;wood:5;stone:4;main:1;farm:1;storage:2;market:1;main:4;storage:1;hide:2;main:1;smith:1;wall:1;farm:3;main:1;smith:4;barracks:3;stable:1;storage:1;farm:1;stable:2;market:2;storage:1;hide:3;wall:4$q$, beschreibung=$d$Weg von KRORETTEF 100 (FetterOrk de260) bis LKav-Forschung, Stand 10.10.2026: HG 10, Kaserne 5, Schmiede 5, Stall 3, Markt 3, Holz 8, Lehm 7, Eisen 9, Hof 6, Speicher 6, Versteck 5, Wall 5. Frühe Kaserne 2 für die Truppen-Aufgaben, Eisen früh für LKav. Ausbau-Belohnungen (150/150/100 je Stufe) abholen lassen; LKav nach Stall 1 in der Schmiede erforschen (von Hand). Danach: LKav-Ausbau W260.$d$
 where team_id is null and lower(name) in (lower('LKav-Rush W260'), lower('LKav-Push W260'));
insert into public.bau_vorlagen (team_id, name, beschreibung, welt, queue, erstellt_von)
 select null, 'LKav-Ausbau W260', $d$Fortsetzung von LKav-Push W260 (enthält deren Schritte, setzt bei Stall 3 an). Stall 5 zuerst (Ausbildung schneller), danach Minen nach bestem Verhältnis Mehrproduktion/Kosten, gewichtet nach Bedarf (LKav 125/100/250 + Bau). Speicher wächst mit, sodass er mind. 10 Std. Produktion fasst (nichts läuft über); Bauernhof hält 15 % Platz frei für LKav-Nachschub; HG folgt den Minen (höchstens 3 Stufen dahinter), Stall 10 ab Minen ~16. Ende: Minen 23, HG 20, Hof 22, Speicher 21, Markt 10, Schmiede 20, Wall 10, Adelshof 1. Simulation ohne Beute und Belohnungen, mit 40 % des Einkommens für LKav - echte Zeiten deutlich kürzer.$d$, 'de260', $q$main:1;farm:1;storage:1;iron:4;wood:1;stone:1;wood:1;stone:1;wood:1;stone:1;main:2;barracks:2;iron:5;wood:5;stone:4;main:1;farm:1;storage:2;market:1;main:4;storage:1;hide:2;main:1;smith:1;wall:1;farm:3;main:1;smith:4;barracks:3;stable:1;storage:1;farm:1;stable:2;market:2;storage:1;hide:3;wall:4;stable:2;stone:1;wood:1;stone:1;wood:1;iron:1;stone:1;wood:1;iron:1;stone:1;wood:1;iron:1;stone:1;wood:1;storage:1;iron:1;stone:1;wood:1;storage:1;farm:1;main:1;iron:1;farm:1;stone:1;wood:1;main:1;farm:1;iron:1;stone:1;wood:1;storage:1;farm:1;main:1;iron:1;farm:1;stone:1;stable:3;wood:1;storage:1;farm:1;main:1;stable:1;iron:1;farm:1;stone:1;wood:1;main:1;farm:1;stable:1;iron:1;stone:1;farm:1;wood:1;storage:1;main:1;iron:1;farm:1;stone:1;wood:1;storage:1;main:1;farm:1;iron:1;stone:1;wood:1;storage:1;farm:1;main:1;iron:1;farm:1;stone:1;wood:1;main:1;farm:1;storage:1;iron:1;stone:1;wood:1;farm:1;main:1;iron:1;farm:1;stone:1;market:7;smith:13;storage:1;smith:1;storage:1;smith:1;storage:5;wall:5;snob:1$q$, erstellt_von from public.bau_vorlagen
 where team_id is null and lower(name)=lower('LKav-Push W260')
   and not exists (select 1 from public.bau_vorlagen where team_id is null and lower(name)=lower('LKav-Ausbau W260'));
